parameters.jsCode:
const analysis = $input.item.json.response;
const bugData = $('Webhook - Bug Report').item.json;

// Extraer información del análisis
const severityMatch = analysis.match(/severidad[:\s]*(crítico|alto|medio|bajo)/i);
const categoryMatch = analysis.match(/categoría[:\s]*(frontend|backend|database|api|ui\/ux|performance|security)/i);
const timeMatch = analysis.match(/(\d+)\s*horas?/i);
const priorityMatch = analysis.match(/prioridad[:\s]*(crítica|alta|media|baja)/i);

const severity = severityMatch ? severityMatch[1].toLowerCase() : 'medio';
const category = categoryMatch ? categoryMatch[1].toLowerCase() : 'backend';
const estimatedHours = timeMatch ? parseInt(timeMatch[1]) : 4;
const priority = priorityMatch ? priorityMatch[1].toLowerCase() : 'media';

// Asignar puntuación
const severityScore = {
  'crítico': 10,
  'alto': 7,
  'medio': 5,
  'bajo': 2
};

const score = severityScore[severity] || 5;

return {
  json: {
    title: bugData.title,
    description: bugData.description,
    analysis: analysis,
    severity: severity,
    category: category,
    estimatedHours: estimatedHours,
    priority: priority,
    score: score,
    timestamp: new Date().toISOString(),
    status: 'open'
  }
};

